"webhookResult\" class=\"result-box full\">وضعیت وبهوک اینجا نمایش داده می‌شود.</pre>\n        </div>\n      </section>\n\n      <section class=\"panel-section\" id=\"products\">\n        <div class=\"section-head\">\n          <div>\n            <h2>محصولات</h2>\n            <p>ورود دستی، خروجی CSV و ورود گروهی از فایل خروجی اکسل.</p>\n          </div>\n          <div class=\"action-row\">\n            <button id=\"downloadTemplateBtn\" class=\"btn\" type=\"button\">قالب CSV</button>\n            <button id=\"exportProductsBtn\" class=\"btn\" type=\"button\">خروجی CSV</button>\n          </div>\n        </div>\n\n        <div class=\"two-column\">\n          <form id=\"productForm\" class=\"form-stack\">\n            <input name=\"name\" placeholder=\"نام محصول\" required />\n            <input name=\"sku\" dir=\"ltr\" placeholder=\"SKU یا کد کالا\" />\n            <input name=\"category\" placeholder=\"دسته‌بندی\" />\n            <input name=\"price\" inputmode=\"numeric\" placeholder=\"قیمت تومان\" />\n            <input name=\"stock\" inputmode=\"numeric\" placeholder=\"موجودی\" />\n            <textarea name=\"description\" placeholder=\"توضیحات کوتاه محصول\"></textarea>\n            <button class=\"btn primary\" type=\"submit\">ثبت محصول</button>\n          </form>\n\n          <div class=\"upload-panel\">\n            <strong>ورود گروهی از CSV</strong>\n            <p>ستون‌ها باید دقیقا این‌ها باشند: <code dir=\"ltr\">sku,name,category,price,stock,description</code></p>\n            <label class=\"file-control\">\n              <input id=\"csvFile\" type=\"file\" accept=\".csv,text/csv\" />\n              <span id=\"csvFileName\">انتخاب فایل CSV</span>\n            </label>\n            <button id=\"importCsvBtn\" class=\"btn secondary\" type=\"button\">ورود محصولات</button>\n            <pre id=\"importResult\" class=\"result-box\">نتیجه ورود اینجا نمایش داده می‌شود.</pre>\n          </div>\n        </div>\n\n        <div class=\"table-toolbar\">\n          <input id=\"productSearch\" placeholder=\"جستجو در محصولات\" />\n          <button id=\"searchProductsBtn\" class=\"btn\" type=\"button\">جستجو</button>\n        </div>\n        <div class=\"table-wrap\"><table id=\"productsTable\"></table></div>\n      </section>\n\n      <section class=\"panel-section\" id=\"faq\">\n        <div class=\"section-head\">\n          <div>\n            <h2>دانش‌نامه و FAQ</h2>\n            <p>پاسخ‌های قابل اعتماد ربات از این بخش تغذیه می‌شود.</p>\n          </div>\n        </div>\n        <form id=\"faqForm\" class=\"form-grid faq-form\">\n          <input name=\"question\" placeholder=\"سوال مشتری\" required />\n          <input name=\"answer\" placeholder=\"پاسخ کوتاه و دقیق\" required />\n          <button class=\"btn primary\" type=\"submit\">ثبت FAQ</button>\n        </form>\n        <div class=\"table-wrap\"><table id=\"faqTable\"></table></div>\n      </section>\n\n      <section class=\"panel-section\" id=\"customers\">\n        <div class=\"section-head\">\n          <div>\n            <h2>مشتریان</h2>\n            <p>کاربرانی که از تلگرام با ربات گفتگو کرده‌اند.</p>\n          </div>\n        </div>\n        <div class=\"table-wrap\"><table id=\"customersTable\"></table></div>\n      </section>\n\n      <section class=\"panel-section\" id=\"messages\">\n        <div class=\"section-head\">\n          <div>\n            <h2>پیام‌ها</h2>\n            <p>آخرین پیام‌های ورودی و خروجی ربات.</p>\n          </div>\n        </div>\n        <div class=\"table-wrap\"><table id=\"messagesTable\"></table></div>\n      </section>\n\n      <section class=\"panel-section\" id=\"orders\">\n        <div class=\"section-head\">\n          <div>\n            <h2>سفارش‌ها و پرداخت</h2>\n            <p>سفارش‌های ثبت‌شده از ربات، وضعیت پرداخت، فاکتور و پیگیری را مدیریت کنید.</p>\n          </div>\n          <div class=\"action-row\">\n            <button id=\"exportOrdersBtn\" class=\"btn\" type=\"button\">خروجی سفارش‌ها</button>\n          </div>\n        </div>\n        <form id=\"orderForm\" class=\"form-grid order-form\">\n          <input name=\"total_amount\" inputmode=\"numeric\" placeholder=\"مبلغ کل\" />\n          <input name=\"customer_phone\" dir=\"ltr\" placeholder=\"شماره موبایل مشتری\" />\n          <select name=\"status\">\n            <option value=\"draft\">پیش‌نویس</option>\n            <option value=\"awaiting_payment\">در انتظار پرداخت</option>\n            <option value=\"payment_reported\">پرداخت اعلام شده</option>\n            <option value=\"paid\">پرداخت تایید شده</option>\n            <option value=\"confirmed\">تایید شده</option>\n            <option value=\"sent\">ارسال شده</option>\n            <option value=\"cancelled\">لغو شده</option>\n          </select>\n          <select name=\"payment_status\">\n            <option value=\"unpaid\">پرداخت نشده</option>\n            <option value=\"reported\">رسید ارسال شده</option>\n            <option value=\"verified\">تایید پرداخت</option>\n          </select>\n          <input name=\"payment_reference\" placeholder=\"شماره پیگیری پرداخت\" />\n          <input name=\"notes\" placeholder=\"یادداشت سفارش\" />\n          <button class=\"btn primary\" type=\"submit\">ثبت سفارش</button>\n        </form>\n        <div class=\"table-wrap\"><table id=\"ordersTable\"></table></div>\n      </section>\n\n      <section class=\"panel-section\" id=\"leads\">\n        <div class=\"section-head\">\n          <div>\n            <h2>درخواست‌ها و سرنخ‌ها</h2>\n            <p>پیام‌هایی که نیاز به پیگیری فروش یا پاسخ اپراتور دارند.</p>\n          </div>\n        </div>\n        <div class=\"table-wrap\"><table id=\"leadsTable\"></table></div>\n      </section>\n\n      <section class=\"panel-section\" id=\"ai-test\">\n        <div class=\"section-head\">\n          <div>\n            <h2>تست پاسخ هوشمند</h2>\n            <p>پیش از اتصال تلگرام، پاسخ ربات را با داده‌های همین پنل بررسی کنید.</p>\n          </div>\n        </div>\n        <div class=\"ai-box\">\n          <textarea id=\"aiQuestion\" placeholder=\"مثلا: گوشی زیر ۲۰ میلیون چی دارید؟\"></textarea>\n          <button id=\"testAiBtn\" class=\"btn primary\" type=\"button\">تولید پاسخ</button>\n          <div id=\"aiAnswer\" class=\"answer-box\">پاسخ اینجا نمایش داده می‌شود.</div>\n        </div>\n      </section>\n\n      <section class=\"panel-section\" id=\"settings\">\n        <div class=\"section-head\">\n          <div>\n            <h2>تنظیمات ربات</h2>\n            <p>متن‌های اصلی و نام فروشگاه را برای کسب‌وکار خود تنظیم کنید.</p>\n          </div>\n        </div>\n        <form id=\"settingsForm\" class=\"form-stack\">\n          <input name=\"shop_name\" placeholder=\"نام فروشگاه\" />\n          <input name=\"business_hours\" placeholder=\"ساعت پاسخگویی\" />\n          <input name=\"currency\" placeholder=\"واحد پول، مثلا تومان\" />\n          <input name=\"support_phone\" dir=\"ltr\" placeholder=\"شماره پشتیبانی\" />\n          <input name=\"payment_card\" dir=\"ltr\" placeholder=\"شماره کارت برای پرداخت دستی\" />\n          <input name=\"payment_iban\" dir=\"ltr\" placeholder=\"شماره شبا\" />\n          <input name=\"payment_account_name\" placeholder=\"نام صاحب حساب\" />\n          <input name=\"payment_link\" dir=\"ltr\" placeholder=\"لینک پرداخت یا صفحه پرداخت\" />\n          <input name=\"order_prefix\" dir=\"ltr\" placeholder=\"پیشوند کد سفارش، مثلا SB\" />\n          <textarea name=\"delivery_info\" placeholder=\"توضیح ارسال و تحویل\"></textarea>\n          <textarea name=\"welcome_message\" placeholder=\"پیام خوش‌آمد ربات\"></textarea>\n          <textarea name=\"operator_message\" placeholder=\"پیام ارجاع به اپراتور\"></textarea>\n          <button class=\"btn primary\" type=\"submit\">ذخیره تنظیمات پرداخت و ربات</button>\n        </form>\n      </section>\n\n      <section class=\"panel-section guide\" id=\"guide\">\n        <div class=\"section-head\">\n          <div>\n            <h2>راهنمای اتصال سریع</h2>\n            <p>راهنمای کامل در README فارسی پروژه قرار دارد.</p>\n          </div>\n        </div>\n        <ol>\n          <li>در پوشه <code>worker</code> دستور <code>npm install</code> را اجرا کنید.</li>\n          <li><code>wrangler.toml.example</code> و <code>.dev.vars.example</code> را کپی کنید و فقط روی سیستم خودتان مقدار بدهید.</li>\n          <li>با Wrangler دیتابیس D1 را بسازید و migration را اجرا کنید.</li>\n          <li>Secretهای Worker را با <code>wrangler secret put</code> تنظیم کنید.</li>\n          <li>Worker را deploy کنید، سپس آدرس آن و ADMIN_TOKEN را در همین پنل وارد کنید.</li>\n          <li>Webhook تلگرام را از دکمه «تنظیم وبهوک تلگرام» داخل همین پنل تنظیم کنید.</li>\n          <li>برای فروش خودکار، شماره کارت/شبا یا لینک پرداخت را در بخش تنظیمات وارد کنید.</li>\n          <li>مشتری در ربات با «خرید کد محصول» فاکتور می‌گیرد و بعد از پرداخت رسید را ارسال می‌کند.</li>\n        </ol>\n      </section>\n    </main>\n  </div>\n\n  <div id=\"toast\" class=\"toast\" role=\"status\" aria-live=\"polite\"></div>\n  <script src=\"assets/app.js\"></script>\n</body>\n</html>\n";

export const PANEL_CSS = ":root {\n  color-scheme: dark light;\n  --bg: #111318;\n  --bg-soft: #171b22;\n  --panel: rgba(255, 255, 255, 0.07);\n  --panel-strong: rgba(255, 255, 255, 0.11);\n  --text: #f4f7fb;\n  --muted: #aeb8c8;\n  --line: rgba(255, 255, 255, 0.13);\n  --green: #42d69a;\n  --blue: #79a8ff;\n  --amber: #f3c969;\n  --rose: #ff7896;\n  --violet: #b99cff;\n  --cyan: #6fd4e8;\n  --danger: #ff6b80;\n  --shadow: 0 18px 50px rgba(0, 0, 0, 0.32);\n  --radius: 8px;\n  font-family: Tahoma, Arial, sans-serif;\n}\n\n* { box-sizing: border-box; }\nhtml { scroll-behavior: smooth; }\nbody {\n  margin: 0;\n  min-height: 100vh;\n  color: var(--text);\n  background:\n    linear-gradient(145deg, rgba(66, 214, 154, 0.12), transparent 34%),\n    linear-gradient(315deg, rgba(121, 168, 255, 0.13), transparent 38%),\n    var(--bg);\n}\n\nbutton, input, textarea, select { font: inherit; }\nbutton { white-space: nowrap; }\na { color: inherit; text-decoration: none; }\ncode { direction: ltr; unicode-bidi: plaintext; }\n\n.app-shell {\n  display: grid;\n  grid-template-columns: 280px minmax(0, 1fr);\n  min-height: 100vh;\n}\n\n.sidebar {\n  position: sticky;\n  top: 0;\n  height: 100vh;\n  padding: 22px;\n  background: rgba(10, 12, 16, 0.78);\n  border-left: 1px solid var(--line);\n  backdrop-filter: blur(16px);\n}\n\n.brand {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  padding: 12px;\n  border: 1px solid var(--line);\n  border-radius: var(--radius);\n  background: var(--panel);\n}\n\n.brand-mark {\n  width: 42px;\n  height: 42px;\n  display: grid;\n  place-items: center;\n  border-radius: var(--radius);\n  color: #0d1117;\n  font-weight: 900;\n  background: linear-gradient(135deg, var(--green), var(--blue));\n}\n\n.brand strong { display: block; font-size: 16px; }\n.brand small { color: var(--muted); }\n\n.nav {\n  display: grid;\n  gap: 6px;\n  margin: 22px 0;\n}\n\n.nav a {\n  padding: 11px 12px;\n  border-radius: var(--radius);\n  color: var(--muted);\n  transition: background 0.18s ease, color 0.18s ease;\n}\n\n.nav a:hover,\n.nav a.active {\n  color: var(--text);\n  background: var(--panel-strong);\n}\n\n.connection-card {\n  padding: 14px;\n  border: 1px solid rgba(66, 214, 154, 0.28);\n  border-radius: var(--radius);\n  background: rgba(66, 214, 154, 0.08);\n}\n\n.connection-card span {\n  display: block;\n  color: var(--muted);\n  font-size: 13px;\n  margin-bottom: 6px;\n}\n\n.connection-card strong { color: var(--green); }\n\n.main {\n  width: 100%;\n  max-width: 1500px;\n  padding: 28px;\n}\n\n.topbar {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  gap: 20px;\n  min-height: 210px;\n  padding: 28px;\n  border: 1px solid var(--line);\n  border-radius: var(--radius);\n  background:\n    linear-gradient(135deg, rgba(255, 255, 255, 0.12), rgba(255, 255, 255, 0.04)),\n    rgba(255, 255, 255, 0.04);\n  box-shadow: var(--shadow);\n}\n\n.eyebrow {\n  margin: 0 0 8px;\n  color: var(--green);\n  font-weight: 800;\n}\n\nh1 {\n  margin: 0;\n  font-size: clamp(30px, 4.8vw, 54px);\n  line-height: 1.2;\n}\n\nh2 {\n  margin: 0;\n  font-size: 22px;\n}\n\np {\n  color: var(--muted);\n  line-height: 1.85;\n}\n\n.top-actions,\n.action-row,\n.table-toolbar {\n  display: flex;\n  gap: 10px;\n  align-items: center;\n  flex-wrap: wrap;\n}\n\n.stats-grid {\n  display: grid;\n  grid-template-columns: repeat(6, minmax(0, 1fr));\n  gap: 14px;\n  margin: 18px 0;\n}\n\n.stat-card,\n.panel-section {\n  border: 1px solid var(--line);\n  border-radius: var(--radius);\n  background: var(--panel);\n  box-shadow: var(--shadow);\n}\n\n.stat-card {\n  min-height: 116px;\n  padding: 18px;\n}\n\n.stat-card span {\n  color: var(--muted);\n  font-size: 14px;\n}\n\n.stat-card strong {\n  display: block;\n  margin-top: 16px;\n  font-size: 34px;\n}\n\n.tone-green { border-color: rgba(66, 214, 154, 0.28); }\n.tone-blue { border-color: rgba(121, 168, 255, 0.28); }\n.tone-amber { border-color: rgba(243, 201, 105, 0.30); }\n.tone-rose { border-color: rgba(255, 120, 150, 0.30); }\n.tone-violet { border-color: rgba(185, 156, 255, 0.30); }\n.tone-cyan { border-color: rgba(111, 212, 232, 0.30); }\n\n.panel-section {\n  padding: 22px;\n  margin-bottom: 18px;\n}\n\n.section-head {\n  display: flex;\n  justify-content: space-between;\n  gap: 16px;\n  align-items: start;\n  margin-bottom: 16px;\n}\n\n.section-head p { margin: 6px 0 0; }\n\n.form-grid {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 12px;\n}\n\n.form-grid.faq-form {\n  grid-template-columns: 1fr 1fr 150px;\n  align-items: end;\n}\n\n.form-grid.order-form {\n  grid-template-columns: 180px 170px 1fr 150px;\n  align-items: end;\n}\n\n.form-stack {\n  display: grid;\n  gap: 12px;\n}\n\n.two-column {\n  display: grid;\n  grid-template-columns: minmax(280px, 410px) 1fr;\n  gap: 14px;\n  align-items: stretch;\n}\n\n.full { grid-column: 1 / -1; }\n\nlabel {\n  display: grid;\n  gap: 7px;\n  color: var(--muted);\n}\n\ninput,\ntextarea,\nselect {\n  width: 100%;\n  border: 1px solid var(--line);\n  border-radius: var(--radius);\n  background: rgba(8, 10, 14, 0.62);\n  color: var(--text);\n  padding: 12px 13px;\n  outline: none;\n  min-height: 44px;\n}\n\ntextarea {\n  min-height: 112px;\n  resize: vertical;\n}\n\ninput:focus,\ntextarea:focus,\nselect:focus {\n  border-color: rgba(66, 214, 154, 0.7);\n  box-shadow: 0 0 0 3px rgba(66, 214, 154, 0.12);\n}\n\nselect {\n  appearance: none;\n  background-image: linear-gradient(45deg, transparent 50%, var(--muted) 50%), linear-gradient(135deg, var(--muted) 50%, transparent 50%);\n  background-position: left 16px center, left 10px center;\n  background-size: 6px 6px, 6px 6px;\n  background-repeat: no-repeat;\n}\n\n.btn {\n  min-height: 44px;\n  border: 1px solid var(--line);\n  border-radius: var(--radius);\n  padding: 10px 15px;\n  color: var(--text);\n  background: rgba(255, 255, 255, 0.08);\n  cursor: pointer;\n  transition: transform 0.18s ease, background 0.18s ease, opacity 0.18s ease;\n}\n\n.btn:hover { transform: translateY(-1px); background: rgba(255, 255, 255, 0.13); }\n.btn:disabled { cursor: wait; opacity: 0.62; transform: none; }\n.btn.primary {\n  color: #0b1117;\n  border-color: transparent;\n  background: linear-gradient(135deg, var(--green), var(--blue));\n  font-weight: 900;\n}\n.btn.secondary {\n  border-color: rgba(66, 214, 154, 0.32);\n  background: rgba(66, 214, 154, 0.12);\n}\n.btn.danger {\n  border-color: rgba(255, 107, 128, 0.42);\n  color: #ffd8de;\n  background: rgba(255, 107, 128, 0.12);\n}\n\n.upload-panel {\n  display: grid;\n  gap: 12px;\n  align-content: start;\n  padding: 18px;\n  border: 1px dashed rgba(66, 214, 154, 0.34);\n  border-radius: var(--radius);\n  background: rgba(66, 214, 154, 0.06);\n}\n\n.file-control input {\n  position: absolute;\n  inline-size: 1px;\n  block-size: 1px;\n  opacity: 0;\n}\n\n.file-control span {\n  display: block;\n  border: 1px solid var(--line);\n  border-radius: var(--radius);\n  padding: 12px 13px;\n  background: rgba(8, 10, 14, 0.62);\n  color: var(--text);\n  cursor: pointer;\n}\n\n.result-box,\n.answer-box {\n  margin: 0;\n  min-height: 96px;\n  white-space: pre-wrap;\n  overflow: auto;\n  border: 1px solid var(--line);\n  border-radius: var(--radius);\n  background: rgba(0, 0, 0, 0.24);\n  padding: 13px;\n  color: #dffbf1;\n  line-height: 1.8;\n}\n\n.table-toolbar {\n  margin-top: 16px;\n}\n\n.table-toolbar input {\n  max-width: 360px;\n}\n\n.table-wrap {\n  margin-top: 14px;\n  overflow: auto;\n  border: 1px solid var(--line);\n  border-radius: var(--radius);\n}\n\ntable {\n  width: 100%;\n  min-width: 800px;\n  border-collapse: collapse;\n}\n\nth,\ntd {\n  padding: 13px;\n  border-bottom: 1px solid var(--line);\n  color: #e7edf7;\n  text-align: right;\n  vertical-align: top;\n}\n\nth {\n  position: sticky;\n  top: 0;\n  z-index: 1;\n  background: rgba(255, 255, 255, 0.10);\n  color: #ffffff;\n  font-weight: 900;\n}\n\ntbody tr:hover td {\n  background: rgba(255, 255, 255, 0.04);\n}\n\n.empty-row td {\n  text-align: center;\n  color: var(--muted);\n  padding: 26px;\n}\n\n.badge {\n  display: inline-flex;\n  align-items: center;\n  min-height: 26px;\n  padding: 3px 9px;\n  border-radius: 999px;\n  border: 1px solid rgba(66, 214, 154, 0.28);\n  color: #c9f8e5;\n  background: rgba(66, 214, 154, 0.10);\n}\n\n.badge.warn {\n  color: #ffe9b5;\n  border-color: rgba(243, 201, 105, 0.30);\n  background: rgba(243, 201, 105, 0.10);\n}\n\n.badge.danger {\n  color: #ffd8de;\n  border-color: rgba(255, 107, 128, 0.32);\n  background: rgba(255, 107, 128, 0.10);\n}\n\n.row-actions {\n  display: flex;\n  gap: 8px;\n  flex-wrap: wrap;\n}\n\n.ai-box {\n  display: grid;\n  gap: 12px;\n}\n\n.guide code {\n  display: inline-block;\n  padding: 2px 7px;\n  border: 1px solid var(--line);\n  border-radius: 6px;\n  background: rgba(0, 0, 0, 0.25);\n}\n\n.guide li {\n  margin-bottom: 10px;\n  color: #e5edf7;\n  line-height: 1.8;\n}\n\n.toast {\n  position: fixed;\n  left: 22px;\n  bottom: 22px;\n  max-width: min(420px, calc(100vw - 44px));\n  padding: 13px 15px;\n  border: 1px solid var(--line);\n  border-radius: var(--radius);\n  background: #161b23;\n  box-shadow: var(--shadow);\n  color: var(--text);\n  opacity: 0;\n  transform: translateY(12px);\n  pointer-events: none;\n  transition: opacity 0.2s ease, transform 0.2s ease;\n}\n\n.toast.show {\n  opacity: 1;\n  transform: translateY(0);\n}\n\n.toast.ok { border-color: rgba(66, 214, 154, 0.48); }\n.toast.error { border-color: rgba(255, 107, 128, 0.52); color: #ffdbe1; }\n\n@media (prefers-color-scheme: light) {\n  :root {\n    --bg: #eef2f6;\n    --bg-soft: #ffffff;\n    --panel: rgba(255, 255, 255, 0.78);\n    --panel-strong: rgba(255, 255, 255, 0.96);\n    --text: #111827;\n    --muted: #5f6b7a;\n    --line: rgba(17, 24, 39, 0.12);\n    --shadow: 0 18px 45px rgba(27, 39, 58, 0.12);\n  }\n\n  body {\n    background:\n      linear-gradient(145deg, rgba(66, 214, 154, 0.16), transparent 34%),\n      linear-gradient(315deg, rgba(121, 168, 255, 0.16), transparent 38%),\n      var(--bg);\n  }\n\n  .sidebar { background: rgba(255, 255, 255, 0.76); }\n  input, textarea, select, .file-control span { background: rgba(255, 255, 255, 0.72); }\n  .result-box, .answer-box { background: rgba(17, 24, 39, 0.05); color: #14372b; }\n  th, td { color: #1f2937; }\n  th { background: rgba(17, 24, 39, 0.06); color: #111827; }\n  .toast { background: #ffffff; }\n}\n\n@media (max-width: 1120px) {\n  .stats-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }\n  .two-column,\n  .form-grid,\n  .form-grid.faq-form,\n  .form-grid.order-form { grid-template-columns: 1fr; }\n}\n\n@media (max-width: 900px) {\n  .app-shell { grid-template-columns: 1fr; }\n  .sidebar {\n    position: relative;\n    height: auto;\n    border-left: 0;\n    border-bottom: 1px solid var(--line);\n  }\n  .nav { grid-template-columns: repeat(2, minmax(0, 1fr)); }\n  .topbar { flex-direction: column; align-items: stretch; }\n}\n\n@media (max-width: 560px) {\n  .main,\n  .sidebar { padding: 14px; }\n  .stats-grid { grid-template-columns: 1fr; }\n  .panel-section,\n  .topbar { padding: 16px; }\n  h1 { font-size: 30px; }\n  .nav { grid-template-columns: 1fr; }\n  .top-actions,\n  .action-row,\n  .table-toolbar { align-items: stretch; }\n  .top-actions > *,\n  .action-row > *,\n  .table-toolbar > * { width: 100%; }\n  .table-toolbar input { max-width: none; }\n}\n\n/* Payment/order flow upgrades */\n.result-box.full { grid-column: 1 / -1; }\n.row-actions.stacked { display: grid; gap: 8px; min-width: 170px; }\n.row-actions.stacked select { width: 100%; }\n.stat-card strong { white-space: nowrap; }\n#ordersTable td { vertical-align: top; }\n#webhookResult { max-height: 180px; overflow: auto; }\n";

export const PANEL_APP_JS = "const $ = (id) => document.getElementById(id);\nconst fmt = (value) => new Intl.NumberFormat(\"fa-IR\").format(Number(value || 0));\nconst DEFAULT_WORKER_API = window.location.origin || \"https://ai-sales-assistant-worker.hossein97jafari.workers.dev\";\n\nconst state = {\n  apiBase: localStorage.getItem(\"aiSalesApiBase\") || DEFAULT_WORKER_API,\n  token: localStorage.getItem(\"aiSalesAdminToken\") || \"\",\n  busy: false,\n};\n\nfunction escapeHtml(value) {\n  return String(value ?? \"\")\n    .replace(/&/g, \"&amp;\")\n    .replace(/</g, \"&lt;\")\n    .replace(/>/g, \"&gt;\")\n    .replace(/\"/g, \"&quot;\")\n    .replace(/'/g, \"&#039;\");\n}\n\nfunction toLocalDate(value) {\n  if (!value) return \"-\";\n  try {\n    return new Date(value).toLocaleString(\"fa-IR\");\n  } catch {\n    return value;\n  }\n}\n\nfunction statusLabel(value) {\n  const labels = {\n    new: \"جدید\",\n    needs_review: \"نیازمند بررسی\",\n    contacted: \"تماس گرفته شد\",\n    won: \"موفق\",\n    lost: \"ناموفق\",\n    draft: \"پیش‌نویس\",\n    confirmed: \"تایید شده\",\n    sent: \"ارسال شده\",\n    awaiting_payment: \"در انتظار پرداخت\",\n    payment_reported: \"پرداخت اعلام شده\",\n    paid: \"پرداخت تایید شده\",\n    cancelled: \"لغو شده\",\n    unpaid: \"پرداخت نشده\",\n    reported: \"رسید ارسال شده\",\n    verified: \"تایید پرداخت\",\n  };\n  return labels[value] || value || \"-\";\n}\n\nfunction toast(message, type = \"ok\") {\n  const el = $(\"toast\");\n  el.textContent = message;\n  el.className = `toast show ${type}`;\n  window.clearTimeout(toast.timer);\n  toast.timer = window.setTimeout(() => {\n    el.className = \"toast\";\n  }, 3800);\n}\n\nfunction setConnectionStatus(text, ok = false) {\n  $(\"connectionStatus\").textContent = text;\n  $(\"connectionStatus\").style.color = ok ? \"var(--green)\" : \"var(--danger)\";\n}\n\nfunction setBusy(isBusy) {\n  state.busy = isBusy;\n  document.querySelectorAll(\"button\").forEach((button) => {\n    button.disabled = isBusy;\n  });\n}\n\nasync function api(path, options = {}) {\n  if (!state.apiBase || !state.token) {\n    throw new Error(\"ابتدا آدرس Worker و توکن مدیریت را وارد کنید.\");\n  }\n\n  const response = await fetch(`${state.apiBase.replace(/\\/$/, \"\")}${path}`, {\n    ...options,\n    headers: {\n      ...(options.headers || {}),\n      Authorization: `Bearer ${state.token}`,\n    },\n  });\n\n  const contentType = response.headers.get(\"content-type\") || \"\";\n  const data = contentType.includes(\"application/json\") ? await response.json() : await response.text();\n\n  if (!response.ok || data.ok === false) {\n    const error = new Error(data.error || data.message || \"درخواست ناموفق بود.\");\n    error.data = data;\n    error.status = response.status;\n    throw error;\n  }\n\n  return data;\n}\n\nfunction renderTable(table, columns, rows) {\n  if (!rows || !rows.length) {\n    table.innerHTML = `<tbody><tr class=\"empty-row\"><td>داده‌ای برای نمایش وجود ندارد.</td></tr></tbody>`;\n    return;\n  }\n\n  table.innerHTML = `\n    <thead>\n      <tr>${columns.map((column) => `<th>${escapeHtml(column.label)}</th>`).join(\"\")}</tr>\n    </thead>\n    <tbody>\n      ${rows.map((row) => `\n        <tr>\n          ${columns.map((column) => `<td>${column.render ? column.render(row) : escapeHtml(row[column.key] ?? \"-\")}</td>`).join(\"\")}\n        </tr>\n      `).join(\"\")}\n    </tbody>\n  `;\n}\n\nasync function downloadAdminFile(path, filename) {\n  const response = await fetch(`${state.apiBase.replace(/\\/$/, \"\")}${path}`, {\n    headers: { Authorization: `Bearer ${state.token}` },\n  });\n  if (!response.ok) throw new Error(\"دانلود فایل ناموفق بود.\");\n  const blob = await response.blob();\n  const link = document.createElement(\"a\");\n  link.href = URL.createObjectURL(blob);\n  link.download = filename;\n  document.body.appendChild(link);\n  link.click();\n  link.remove();\n  URL.revokeObjectURL(link.href);\n}\n\nasync function loadStats() {\n  const data = await api(\"/api/admin/stats\");\n  $(\"statCustomers\").textContent = fmt(data.stats.customers);\n  $(\"statProducts\").textContent = fmt(data.stats.products);\n  $(\"statLeads\").textContent = fmt(data.stats.leads);\n  $(\"statMessages\").textContent = fmt(data.stats.messages);\n  $(\"statFaqs\").textContent = fmt(data.stats.faqs);\n  $(\"statOrders\").textContent = fmt(data.stats.orders);\n  if ($(\"statRevenue\")) $(\"statRevenue\").textContent = `${fmt(data.stats.revenue)} تومان`;\n  if ($(\"statAwaitingPayment\")) $(\"statAwaitingPayment\").textContent = fmt(data.stats.awaiting_payment);\n}\n\nasync function loadProducts() {\n  const q = encodeURIComponent($(\"productSearch\").value.trim());\n  const data = await api(`/api/admin/products?limit=100${q ? `&q=${q}` : \"\"}`);\n  renderTable($(\"productsTable\"), [\n    { label: \"کد\", render: (row) => `<span dir=\"ltr\">${escapeHtml(row.sku)}</span>` },\n    { label: \"نام محصول\", key: \"name\" },\n    { label: \"دسته\", key: \"category\" },\n    { label: \"قیمت\", render: (row) => `${fmt(row.price)} تومان` },\n    { label: \"موجودی\", render: (row) => `<span class=\"badge\">${fmt(row.stock)}</span>` },\n    { label: \"وضعیت\", render: (row) => row.is_active ? '<span class=\"badge\">فعال</span>' : '<span class=\"badge danger\">غیرفعال</span>' },\n    {\n      label: \"عملیات\",\n      render: (row) => `<div class=\"row-actions\"><button class=\"btn danger\" data-action=\"deactivate-product\" data-id=\"${row.id}\" type=\"button\">غیرفعال</button></div>`,\n    },\n  ], data.products);\n}\n\nasync function loadFaqs() {\n  const data = await api(\"/api/admin/faqs?limit=100\");\n  renderTable($(\"faqTable\"), [\n    { label: \"سوال\", key: \"question\" },\n    { label: \"پاسخ\", key: \"answer\" },\n    { label: \"وضعیت\", render: (row) => row.is_active ? '<span class=\"badge\">فعال</span>' : '<span class=\"badge danger\">غیرفعال</span>' },\n    {\n      label: \"عملیات\",\n      render: (row) => `<button class=\"btn danger\" data-action=\"deactivate-faq\" data-id=\"${row.id}\" type=\"button\">غیرفعال</button>`,\n    },\n  ], data.faqs);\n}\n\nasync function loadCustomers() {\n  const data = await api(\"/api/admin/customers?limit=100\");\n  renderTable($(\"customersTable\"), [\n    { label: \"نام\", key: \"full_name\" },\n    { label: \"نام کاربری\", render: (row) => row.username ? `<span dir=\"ltr\">@${escapeHtml(row.username)}</span>` : \"-\" },\n    { label: \"شناسه تلگرام\", render: (row) => `<span dir=\"ltr\">${escapeHtml(row.telegram_id || \"-\")}</span>` },\n    { label: \"شماره\", key: \"phone\" },\n    { label: \"آخرین بروزرسانی\", render: (row) => toLocalDate(row.updated_at) },\n  ], data.customers);\n}\n\nasync function loadMessages() {\n  const data = await api(\"/api/admin/messages?limit=100\");\n  renderTable($(\"messagesTable\"), [\n    { label: \"مشتری\", render: (row) => escapeHtml(row.full_name || row.username || \"-\") },\n    { label: \"جهت\", render: (row) => row.direction === \"in\" ? '<span class=\"badge warn\">ورودی</span>' : '<span class=\"badge\">خروجی</span>' },\n    { label: \"کانال\", key: \"channel\" },\n    { label: \"متن\", render: (row) => escapeHtml(row.body).slice(0, 220) },\n    { label: \"زمان\", render: (row) => toLocalDate(row.created_at) },\n  ], data.messages);\n}\n\nasync function loadOrders() {\n  const data = await api(\"/api/admin/orders?limit=100\");\n  renderTable($(\"ordersTable\"), [\n    { label: \"کد سفارش\", render: (row) => row.order_code ? `<span dir=\"ltr\">${escapeHtml(row.order_code)}</span>` : `#${fmt(row.id)}` },\n    { label: \"مشتری\", render: (row) => escapeHtml(row.customer_name || row.customer_username || \"-\") },\n    { label: \"موبایل\", render: (row) => `<span dir=\"ltr\">${escapeHtml(row.customer_phone || row.customer_saved_phone || \"-\")}</span>` },\n    { label: \"وضعیت\", render: (row) => `<span class=\"badge\">${escapeHtml(statusLabel(row.status))}</span>` },\n    { label: \"پرداخت\", render: (row) => `<span class=\"badge ${row.payment_status === \"verified\" ? \"\" : \"warn\"}\">${escapeHtml(statusLabel(row.payment_status))}</span>` },\n    { label: \"مبلغ\", render: (row) => `${fmt(row.total_amount)} تومان` },\n    { label: \"آیتم\", render: (row) => fmt(row.items_count) },\n    { label: \"تاریخ\", render: (row) => toLocalDate(row.created_at) },\n    {\n      label: \"عملیات\",\n      render: (row) => `\n        <div class=\"row-actions stacked\">\n          <button class=\"btn secondary\" data-action=\"copy-invoice\" data-code=\"${escapeHtml(row.order_code || row.id)}\" type=\"button\">کپی فاکتور</button>\n          <select data-action=\"order-payment\" data-id=\"${row.id}\" aria-label=\"تغییر پرداخت\">\n            ${[\"unpaid\", \"reported\", \"verified\"].map((status) => `<option value=\"${status}\" ${row.payment_status === status ? \"selected\" : \"\"}>${statusLabel(status)}</option>`).join(\"\")}\n          </select>\n          <select data-action=\"order-status\" data-id=\"${row.id}\" aria-label=\"تغییر وضعیت\">\n            ${[\"awaiting_payment\", \"payment_reported\", \"paid\", \"confirmed\", \"sent\", \"cancelled\"].map((status) => `<option value=\"${status}\" ${row.status === status ? \"selected\" : \"\"}>${statusLabel(status)}</option>`).join(\"\")}\n          </select>\n        </div>\n      `,\n    },\n  ], data.orders);\n}\n\nasync function loadLeads() {\n  const data = await api(\"/api/admin/leads?limit=100\");\n  renderTable($(\"leadsTable\"), [\n    { label: \"نام\", key: \"full_name\" },\n    { label: \"موبایل\", render: (row) => `<span dir=\"ltr\">${escapeHtml(row.phone || \"-\")}</span>` },\n    { label: \"پیام\", render: (row) => escapeHtml(row.message).slice(0, 240) },\n    { label: \"منبع\", key: \"source\" },\n    { label: \"وضعیت\", render: (row) => `<span class=\"badge\">${escapeHtml(statusLabel(row.status))}</span>` },\n    { label: \"تاریخ\", render: (row) => toLocalDate(row.created_at) },\n    {\n      label: \"پیگیری\",\n      render: (row) => `\n        <select data-action=\"lead-status\" data-id=\"${row.id}\" aria-label=\"تغییر وضعیت درخواست\">\n          ${[\"new\", \"needs_review\", \"contacted\", \"won\", \"lost\"].map((status) => `\n            <option value=\"${status}\" ${row.status === status ? \"selected\" : \"\"}>${statusLabel(status)}</option>\n          `).join(\"\")}\n        </select>\n      `,\n    },\n  ], data.leads);\n}\n\nasync function loadSettings() {\n  const data = await api(\"/api/admin/settings\");\n  const form = $(\"settingsForm\");\n  Object.entries(data.settings || {}).forEach(([key, value]) => {\n    if (form.elements[key]) form.elements[key].value = value;\n  });\n}\n\nasync function refreshAll(showToast = false) {\n  try {\n    setBusy(true);\n    await loadStats();\n    await Promise.all([\n      loadProducts(),\n      loadFaqs(),\n      loadCustomers(),\n      loadMessages(),\n      loadOrders(),\n      loadLeads(),\n      loadSettings(),\n    ]);\n    setConnectionStatus(\"متصل\", true);\n    if (showToast) toast(\"اطلاعات بروزرسانی شد.\");\n  } catch (error) {\n    setConnectionStatus(\"قطع یا تنظیم نشده\", false);\n    toast(error.message, \"error\");\n  } finally {\n    setBusy(false);\n  }\n}\n\nfunction formToObject(form) {\n  return Object.fromEntries(new FormData(form).entries());\n}\n\nfunction bindForms() {\n  $(\"apiBase\").value = state.apiBase;\n  $(\"adminToken\").value = state.token;\n\n  $(\"saveConnectionBtn\").addEventListener(\"click\", async () => {\n    state.apiBase = $(\"apiBase\").value.trim();\n    state.token = $(\"adminToken\").value.trim();\n    localStorage.setItem(\"aiSalesApiBase\", state.apiBase);\n    localStorage.setItem(\"aiSalesAdminToken\", state.token);\n    await refreshAll(true);\n  });\n\n  if ($(\"setWebhookBtn\")) {\n    $(\"setWebhookBtn\").addEventListener(\"click\", async () => {\n      try {\n        const data = await api(\"/api/admin/telegram/set-webhook\", { method: \"POST\" });\n        $(\"webhookResult\").textContent = JSON.stringify(data, null, 2);\n        toast(\"وبهوک تلگرام تنظیم شد.\");\n      } catch (error) {\n        $(\"webhookResult\").textContent = error.message;\n        toast(error.message, \"error\");\n      }\n    });\n  }\n\n  if ($(\"webhookInfoBtn\")) {\n    $(\"webhookInfoBtn\").addEventListener(\"click\", async () => {\n      try {\n        const data = await api(\"/api/admin/telegram/webhook-info\");\n        $(\"webhookResult\").textContent = JSON.stringify(data, null, 2);\n        toast(\"وضعیت وبهوک دریافت شد.\");\n      } catch (error) {\n        $(\"webhookResult\").textContent = error.message;\n        toast(error.message, \"error\");\n      }\n    });\n  }\n\n  $(\"refreshBtn\").addEventListener(\"click\", () => refreshAll(true));\n  $(\"searchProductsBtn\").addEventListener(\"click\", loadProducts);\n  $(\"productSearch\").addEventListener(\"keydown\", (event) => {\n    if (event.key === \"Enter\") loadProducts();\n  });\n\n  $(\"seedDemoBtn\").addEventListener(\"click\", async () => {\n    try {\n      setBusy(true);\n      await api(\"/api/admin/demo/seed\", { method: \"POST\" });\n      toast(\"داده دمو ساخته شد.\");\n      await refreshAll();\n    } catch (error) {\n      toast(error.message, \"error\");\n    } finally {\n      setBusy(false);\n    }\n  });\n\n  $(\"productForm\").addEventListener(\"submit\", async (event) => {\n    event.preventDefault();\n    try {\n      await api(\"/api/admin/products\", {\n        method: \"POST\",\n        headers: { \"content-type\": \"application/json\" },\n        body: JSON.stringify(formToObject(event.currentTarget)),\n      });\n      event.currentTarget.reset();\n      toast(\"محصول ثبت شد.\");\n      await refreshAll();\n    } catch (error) {\n      toast(error.message, \"error\");\n    }\n  });\n\n  $(\"faqForm\").addEventListener(\"submit\", async (event) => {\n    event.preventDefault();\n    try {\n      await api(\"/api/admin/faqs\", {\n        method: \"POST\",\n        headers: { \"content-type\": \"application/json\" },\n        body: JSON.stringify(formToObject(event.currentTarget)),\n      });\n      event.currentTarget.reset();\n      toast(\"FAQ ثبت شد.\");\n      await refreshAll();\n    } catch (error) {\n      toast(error.message, \"error\");\n    }\n  });\n\n  $(\"orderForm\").addEventListener(\"submit\", async (event) => {\n    event.preventDefault();\n    try {\n      await api(\"/api/admin/orders\", {\n        method: \"POST\",\n        headers: { \"content-type\": \"application/json\" },\n        body: JSON.stringify(formToObject(event.currentTarget)),\n      });\n      event.currentTarget.reset();\n      toast(\"سفارش ثبت شد.\");\n      await refreshAll();\n    } catch (error) {\n      toast(error.message, \"error\");\n    }\n  });\n\n  $(\"settingsForm\").addEventListener(\"submit\", async (event) => {\n    event.preventDefault();\n    try {\n      await api(\"/api/admin/settings\", {\n        method: \"PATCH\",\n        headers: { \"content-type\": \"application/json\" },\n        body: JSON.stringify(formToObject(event.currentTarget)),\n      });\n      toast(\"تنظیمات ذخیره شد.\");\n      await loadSettings();\n    } catch (error) {\n      toast(error.message, \"error\");\n    }\n  });\n\n  $(\"csvFile\").addEventListener(\"change\", () => {\n    const file = $(\"csvFile\").files[0];\n    $(\"csvFileName\").textContent = file ? file.name : \"انتخاب فایل CSV\";\n  });\n\n  $(\"importCsvBtn\").addEventListener(\"click\", async () => {\n    const file = $(\"csvFile\").files[0];\n    if (!file) return toast(\"فایل CSV را انتخاب کنید.\", \"error\");\n    try {\n      const data = await api(\"/api/admin/products/import-csv\", {\n        method: \"POST\",\n        headers: { \"content-type\": \"text/csv; charset=utf-8\" },\n        body: await file.text(),\n      });\n      $(\"importResult\").textContent = [\n        `کل ردیف‌ها: ${fmt(data.result.total)}`,\n        `ثبت جدید: ${fmt(data.result.inserted)}`,\n        `بروزرسانی: ${fmt(data.result.updated)}`,\n      ].join(\"\\n\");\n      toast(\"ورود محصولات انجام شد.\");\n      await refreshAll();\n    } catch (error) {\n      const result = error.data?.result;\n      $(\"importResult\").textContent = result?.errors?.length\n        ? result.errors.join(\"\\n\")\n        : error.message;\n      toast(error.message, \"error\");\n    }\n  });\n\n  $(\"downloadTemplateBtn\").addEventListener(\"click\", async () => {\n    try {\n      await downloadAdminFile(\"/api/admin/template/products.csv\", \"products-template.csv\");\n    } catch (error) {\n      toast(error.message, \"error\");\n    }\n  });\n\n  $(\"exportProductsBtn\").addEventListener(\"click\", async () => {\n    try {\n      await downloadAdminFile(\"/api/admin/products/export.csv\", \"products-export.csv\");\n    } catch (error) {\n      toast(error.message, \"error\");\n    }\n  });\n\n  if ($(\"exportOrdersBtn\")) {\n    $(\"exportOrdersBtn\").addEventListener(\"click\", async () => {\n      try {\n        await downloadAdminFile(\"/api/admin/orders/export.csv\", \"orders-export.csv\");\n      } catch (error) {\n        toast(error.message, \"error\");\n      }\n    });\n  }\n\n  $(\"testAiBtn\").addEventListener(\"click\", async () => {\n    const question = $(\"aiQuestion\").value.trim();\n    if (!question) return toast(\"یک سوال وارد کنید.\", \"error\");\n    $(\"aiAnswer\").textContent = \"در حال آماده‌سازی پاسخ...\";\n    try {\n      const data = await api(\"/api/admin/ai/test\", {\n        method: \"POST\",\n        headers: { \"content-type\": \"application/json\" },\n        body: JSON.stringify({ question }),\n      });\n      $(\"aiAnswer\").textContent = `${data.answer}\\n\\nمنبع پاسخ: ${data.confidence} | محصول: ${fmt(data.sources.products)} | FAQ: ${fmt(data.sources.faqs)}`;\n    } catch (error) {\n      $(\"aiAnswer\").textContent = error.message;\n      toast(error.message, \"error\");\n    }\n  });\n}\n\nfunction bindDelegatedActions() {\n  document.addEventListener(\"click\", async (event) => {\n    const button = event.target.closest(\"button[data-action]\");\n    if (!button) return;\n\n    try {\n      if (button.dataset.action === \"deactivate-product\") {\n        await api(`/api/admin/products/${button.dataset.id}`, { method: \"DELETE\" });\n        toast(\"محصول غیرفعال شد.\");\n        await refreshAll();\n      }\n      if (button.dataset.action === \"deactivate-faq\") {\n        await api(`/api/admin/faqs/${button.dataset.id}`, { method: \"DELETE\" });\n        toast(\"FAQ غیرفعال شد.\");\n        await refreshAll();\n      }\n      if (button.dataset.action === \"copy-invoice\") {\n        const url = `${state.apiBase.replace(/\\/$/, \"\")}/invoice/${encodeURIComponent(button.dataset.code)}`;\n        await navigator.clipboard.writeText(url);\n        toast(\"لینک فاکتور کپی شد.\");\n      }\n    } catch (error) {\n      toast(error.message, \"error\");\n    }\n  });\n\n  document.addEventListener(\"change\", async (event) => {\n    const select = event.target.closest(\"select[data-action]\");\n    if (!select) return;\n\n    try {\n      if (select.dataset.action === \"lead-status\") {\n        await api(`/api/admin/leads/${select.dataset.id}`, {\n          method: \"PATCH\",\n          headers: { \"content-type\": \"application/json\" },\n          body: JSON.stringify({ status: select.value }),\n        });\n        toast(\"وضعیت درخواست بروزرسانی شد.\");\n        await loadLeads();\n      }\n\n      if (select.dataset.action === \"order-status\") {\n        await api(`/api/admin/orders/${select.dataset.id}`, {\n          method: \"PATCH\",\n          headers: { \"content-type\": \"application/json\" },\n          body: JSON.stringify({ status: select.value }),\n        });\n        toast(\"وضعیت سفارش بروزرسانی شد.\");\n        await loadOrders();\n      }\n\n      if (select.dataset.action === \"order-payment\") {\n        await api(`/api/admin/orders/${select.dataset.id}`, {\n          method: \"PATCH\",\n          headers: { \"content-type\": \"application/json\" },\n          body: JSON.stringify({ payment_status: select.value, status: select.value === \"verified\" ? \"paid\" : undefined }),\n        });\n        toast(\"وضعیت پرداخت بروزرسانی شد.\");\n        await loadOrders();\n      }\n    } catch (error) {\n      toast(error.message, \"error\");\n    }\n  });\n}\n\nfunction bindNavigation() {\n  const links = Array.from(document.querySelectorAll(\".nav a\"));\n  const activate = () => {\n    const hash = window.location.hash || \"#dashboard\";\n    links.forEach((link) => link.classList.toggle(\"active\", link.getAttribute(\"href\") === hash));\n  };\n  links.forEach((link) => link.addEventListener(\"click\", activate));\n  window.addEventListener(\"hashchange\", activate);\n  activate();\n}\n\nbindForms();\nbindDelegatedActions();\nbindNavigation();\nrefreshAll();\n";
